def sha256(path):
    digest = hashlib.sha256()
    with open(path, "rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def percentile(values, fraction):
    if not values:
        return None
    ordered = sorted(values)
    position = fraction * (len(ordered) - 1)
    left = int(position)
    right = min(left + 1, len(ordered) - 1)
    return ordered[left] + (position - left) * (ordered[right] - ordered[left])


def linear_slope(points):
    if len(points) < 3:
        return None
    mean_x = statistics.mean(x for x, _ in points)
    mean_y = statistics.mean(y for _, y in points)
    variance = sum((x - mean_x) ** 2 for x, _ in points)
    return (
        sum((x - mean_x) * (y - mean_y) for x, y in points) / variance
        if variance > 0
        else None
    )


def beat_metrics(reference, predicted, duration, tolerance=0.070):
    (
        "Maximum-cardinality chronological one-to-one matches within a "
        "fixed tolerance."
    )
    reference = [float(value) for value in reference]
    predicted = [float(value) for value in predicted]
    if (
        not math.isfinite(duration)
        or duration <= 0
        or any(not math.isfinite(value) for value in reference + predicted)
    ):
        raise ValueError(
            "finite beat times and positive duration are required"
        )
    if reference != sorted(reference) or predicted != sorted(predicted):
        raise ValueError("beat times must be ordered")
    guard = min(2.0, duration / 10)
    start, end = guard, duration - guard
    truth = [float(t) for t in reference if start <= t < end]
    guesses = [float(t) for t in predicted if start <= t < end]
    matches = []
    left = right = 0
    while left < len(truth) and right < len(guesses):
        error = guesses[right] - truth[left]
        if error < -tolerance:
            right += 1
        elif error > tolerance:
            left += 1
        else:
            matches.append((truth[left], error))
            left += 1
            right += 1
    precision = (
        len(matches) / len(guesses) if guesses else (1.0 if not truth else 0.0)
    )
    recall = (
        len(matches) / len(truth) if truth else (1.0 if not guesses else 0.0)
    )
    f1 = (
        2 * precision * recall / (precision + recall)
        if precision + recall
        else 0.0
    )
    errors_ms = [error * 1000 for _, error in matches]
    slope = linear_slope(matches)
    matched_span = matches[-1][0] - matches[0][0] if len(matches) >= 2 else 0
    reference_span = truth[-1] - truth[0] if len(truth) >= 2 else 0
    span_fraction = matched_span / reference_span if reference_span > 0 else 0
    drift_qualified = (
        recall >= 0.8 and span_fraction >= 0.8 and matched_span >= 8
    )
    windows = []
    window_start = start
    while window_start < end:
        window_end = min(end, window_start + 8)
        local = [
            (t, e * 1000) for t, e in matches if window_start <= t < window_end
        ]
        local_truth = sum(window_start <= t < window_end for t in truth)
        windows.append(
            {
                "start_seconds": window_start,
                "end_seconds": window_end,
                "matched": len(local),
                "reference_beats": local_truth,
                "recall": len(local) / local_truth if local_truth else None,
                "median_signed_error_ms": (
                    statistics.median(e for _, e in local) if local else None
                ),
            }
        )
        window_start = window_end
    return {
        "tolerance_seconds": tolerance,
        "evaluated_start_seconds": start,
        "evaluated_end_seconds": end,
        "reference_beats": len(truth),
        "predicted_beats": len(guesses),
        "one_to_one_matches": len(matches),
        "precision": precision,
        "recall": recall,
        "f1": f1,
        "median_signed_error_ms": (
            statistics.median(errors_ms) if errors_ms else None
        ),
        "median_absolute_error_ms": (
            statistics.median(abs(e) for e in errors_ms) if errors_ms else None
        ),
        "p95_absolute_error_ms": percentile([abs(e) for e in errors_ms], 0.95),
        "drift_slope_ms_per_minute": (
            slope * 60000 if slope is not None and drift_qualified else None
        ),
        "matched_error_slope_raw_ms_per_minute": (
            slope * 60000 if slope is not None else None
        ),
        "drift_fit_matched_reference_fraction": recall,
        "drift_fit_matched_span_fraction": span_fraction,
        "drift_fit_qualified": drift_qualified,
        "drift_fit_scope": (
            "matched-only linear error trend; qualified only with >=80% "
            "beat/span coverage and >=8 seconds span"
        ),
        "per_window": windows,
    }


def true_window_bpm(beats, start, end):
    intervals = [
        b - a for a, b in zip(beats, beats[1:]) if start <= (a + b) / 2 < end
    ]
    return 60 / statistics.mean(intervals) if intervals else None


def tempo_change_metrics(truth, report):
    results = []
    windows = report.get("local_bpm_windows", [])
    changes = sorted(
        truth.get("tempo_changes", []), key=lambda item: item["time_seconds"]
    )
    for index, change in enumerate(changes):
        before, after = change["bpm_before"], change["bpm_after"]
        midpoint = (before + after) / 2
        start = (
            (changes[index - 1]["time_seconds"] + change["time_seconds"]) / 2
            if index
            else 0
        )
        end = (
            (change["time_seconds"] + changes[index + 1]["time_seconds"]) / 2
            if index + 1 < len(changes)
            else math.inf
        )
        relevant = [
            w
            for w in windows
            if start <= (w["start_seconds"] + w["end_seconds"]) / 2 < end
            and w.get("bpm") is not None
        ]
        points = [
            ((w["start_seconds"] + w["end_seconds"]) / 2, w["bpm"])
            for w in relevant
        ]
        before_windows = [
            w for w in relevant if w["end_seconds"] <= change["time_seconds"]
        ]
        after_windows = [
            w for w in relevant if w["start_seconds"] >= change["time_seconds"]
        ]
        detected = None
        bracketed = (
            before_windows
            and after_windows
            and abs(before_windows[-1]["bpm"] - before) <= before * 0.05
            and abs(after_windows[0]["bpm"] - after) <= after * 0.05
        )
        if bracketed:
            for (a_time, a_bpm), (b_time, b_bpm) in zip(points, points[1:]):
                crosses = (
                    a_bpm < midpoint <= b_bpm
                    if after > before
                    else b_bpm <= midpoint < a_bpm
                )
                if crosses and b_bpm != a_bpm:
                    candidate = a_time + (midpoint - a_bpm) / (
                        b_bpm - a_bpm
                    ) * (b_time - a_time)
                    if detected is None or abs(
                        candidate - change["time_seconds"]
                    ) < abs(detected - change["time_seconds"]):
                        detected = candidate
        results.append(
            {
                **change,
                "estimated_change_seconds": detected,
                "change_time_error_seconds": (
                    detected - change["time_seconds"]
                    if detected is not None
                    else None
                ),
                "transition_locally_bracketed": bool(bracketed),
                "method": (
                    "midpoint crossing of exported 8-second local BPM "
                    "windows, 4-second stride; isolated using neighboring "
                    "true changes"
                ),
                "limitation": (
                    "requires pure before/after windows; nearby changes or "
                    "short tails may be unresolved"
                ),
            }
        )
    return results


def truth_metrics(entry, report, tolerance):
    truth = entry.get("truth")
    if truth is None:
        return {
            "ground_truth_available": False,
            "accuracy": None,
            "reason": (
                "uploaded recording has no externally annotated tempo/beat "
                "truth"
            ),
        }
    result = {"ground_truth_available": True, "status": report.get("status")}
    if report.get("status") != "success":
        result["accuracy"] = None
        result["noresult_expected"] = truth.get("expected_noresult", False)
        return result
    result["beats"] = beat_metrics(
        truth["beat_times_seconds"],
        report.get("beat_times_seconds", []),
        report["duration_seconds"],
        tolerance,
    )
    target = truth.get("constant_bpm")
    result["absolute_bpm_error"] = (
        abs(report["bpm"] - target) if target is not None else None
    )
    result["relative_bpm_error"] = (
        abs(report["bpm"] / target - 1) if target is not None else None
    )
    result["global_bpm_error_scope"] = (
        "not defined for changing tempo"
        if target is None
        else "exact tempo; octave errors are not forgiven"
    )
    local = []
    for window in report.get("local_bpm_windows", []):
        mean_interval_bpm = true_window_bpm(
            truth["beat_times_seconds"],
            window["start_seconds"],
            window["end_seconds"],
        )
        boundary_kinds = []
        for key, label in (
            ("phase_edits", "phase edit"),
            ("tempo_changes", "tempo change"),
        ):
            if any(
                window["start_seconds"]
                < boundary["time_seconds"]
                < window["end_seconds"]
                for boundary in truth.get(key, [])
            ):
                boundary_kinds.append(label)
        target = mean_interval_bpm if not boundary_kinds else None
        value = window.get("bpm")
        local.append(
            {
                **window,
                "true_bpm": target,
                "true_mean_interval_bpm": mean_interval_bpm,
                "excluded_from_tempo_error": "; ".join(boundary_kinds) or None,
                "absolute_bpm_error": (
                    abs(value - target)
                    if value is not None and target is not None
                    else None
                ),
            }
        )
    result["local_bpm_windows"] = local
    result["local_bpm_metric_scope"] = (
        "60/mean true inter-beat interval; windows crossing discrete "
        "phase/tempo edits are excluded from errors"
    )
    errors = [
        window["absolute_bpm_error"]
        for window in local
        if window["absolute_bpm_error"] is not None
    ]
    result["local_bpm_mean_absolute_error"] = (
        statistics.mean(errors) if errors else None
    )
    result["local_bpm_p95_absolute_error"] = percentile(errors, 0.95)
    result["tempo_changes"] = tempo_change_metrics(truth, report)
    return result


def assert_same_pcm(first, second):
    fields = (
        "source_sha256",
        "source_size_bytes",
        "pcm_sha256",
        "decoded_frames",
        "sample_rate",
        "channels",
    )
    for field in fields:
        if (
            field not in first
            or field not in second
            or first[field] != second[field]
        ):
            raise ValueError(
                f"paired inputs differ or are unavailable: {field}"
            )


def paired_metrics(reference, candidate, tolerance):
    assert_same_pcm(reference, candidate)
    result = {
        "reference_config": reference["config"],
        "candidate_config": candidate["config"],
        "identical_source_and_decoded_pcm": True,
        "reference_status": reference["status"],
        "candidate_status": candidate["status"],
        "timing_ratio_has_two_successful_results": reference["status"]
        == candidate["status"]
        == "success",
        "analysis_time_ratio_candidate_over_reference": (
            candidate["analysis_ms"] / reference["analysis_ms"]
            if reference.get("analysis_ms", 0) > 0
            else None
        ),
        "peak_process_rss_ratio_candidate_over_reference": (
            candidate["peak_rss_bytes"] / reference["peak_rss_bytes"]
            if reference.get("peak_rss_bytes")
            and candidate.get("peak_rss_bytes")
            else None
        ),
        "agreement_is_not_accuracy": True,
    }
    if reference["status"] == candidate["status"] == "success":
        result["bpm_difference_candidate_minus_reference"] = (
            candidate["bpm"] - reference["bpm"]
        )
        result["bpm_ratio_candidate_over_reference"] = (
            candidate["bpm"] / reference["bpm"]
        )
        result["beat_agreement"] = beat_metrics(
            reference["beat_times_seconds"],
            candidate["beat_times_seconds"],
            reference["duration_seconds"],
            tolerance,
        )
        result["local_bpm_differences"] = [
            {
                "start_seconds": a["start_seconds"],
                "end_seconds": a["end_seconds"],
                "candidate_minus_reference": (
                    b["bpm"] - a["bpm"]
                    if a.get("bpm") is not None and b.get("bpm") is not None
                    else None
                ),
            }
            for a, b in zip(
                reference.get("local_bpm_windows", []),
                candidate.get("local_bpm_windows", []),
            )
            if (a["start_seconds"], a["end_seconds"])
            == (b["start_seconds"], b["end_seconds"])
        ]
    return result


def generate_synthetic(directory):
    directory.mkdir(parents=True, exist_ok=True)
    cases = [
        ("constant120", 32, 44100, 120, "constant"),
        ("fractional132_06", 32, 44100, 132.06, "constant"),
        ("accented174", 48, 44100, 174, "accent"),
        ("constant120_48k", 32, 48000, 120, "constant"),
        ("step120_138", 48, 44100, 120, "step"),
        ("drift110_140", 48, 44100, 110, "drift"),
        ("phase_edit120", 48, 44100, 120, "phase"),
        ("silence", 12, 44100, 120, "silence"),
        ("short120", 3, 44100, 120, "short"),
    ]
    entries = []
    for name, duration, rate, bpm, kind in cases:
        origin = 0.2
        beats = []
        if kind != "silence":
            position = origin
            index = 0
            while position < duration:
                beats.append(round(position * rate) / rate)
                index += 1
                if kind == "drift":
                    # Integral of linear BPM(t): b*t + k*t²/2 = 60*beatIndex.
                    slope = 30 / (duration - origin)
                    relative = (
                        120
                        * index
                        / (bpm + math.sqrt(bpm * bpm + 120 * slope * index))
                    )
                    position = origin + relative
                elif kind == "step":
                    position += 60 / (120 if position < 24 else 138)
                else:
                    position = origin + index * 60 / bpm
                    if kind == "phase" and position >= 24:
                        position += 30 / bpm
        mono = [0.0] * (duration * rate)
        pulse = [
            math.exp(-100 * frame / rate)
            * (
                0.8 * math.cos(2 * math.pi * 90 * frame / rate)
                + 0.2 * math.cos(2 * math.pi * 1700 * frame / rate)
            )
            for frame in range(round(0.08 * rate))
        ]
        for index, beat in enumerate(beats):
            start = round(beat * rate)
            level = 0.65 * (0.3 if kind == "accent" and index % 3 else 1)
            for offset in range(min(len(pulse), len(mono) - start)):
                mono[start + offset] += level * pulse[offset]
        samples = array.array("h")
        for value in mono:
            sample = round(max(-1, min(1, value)) * 32767)
            samples.extend((sample, sample))
        if sys.byteorder != "little":
            samples.byteswap()
        path = directory / (name + ".wav")
        with wave.open(str(path), "wb") as output:
            output.setnchannels(2)
            output.setsampwidth(2)
            output.setframerate(rate)
            output.writeframes(samples.tobytes())
        truth = {
            "generator": "deterministic-percussive-pulses-v1",
            "kind": kind,
            "beat_times_seconds": beats,
            "constant_bpm": (
                bpm
                if kind in {"constant", "accent", "short", "phase"}
                else None
            ),
            "expected_noresult": kind in {"silence", "short"},
            "tempo_changes": (
                [
                    {
                        "time_seconds": next(t for t in beats if t >= 24),
                        "bpm_before": 120,
                        "bpm_after": 138,
                    }
                ]
                if kind == "step"
                else []
            ),
        }
        if kind == "phase":
            truth["phase_edits"] = [
                {"time_seconds": 24, "shift_seconds": 30 / bpm}
            ]
        entries.append(
            {"name": name, "path": str(path.resolve()), "truth": truth}
        )
    return entries


def load_inputs(arguments, output):
    entries = (
        generate_synthetic(output / "synthetic") if arguments.synthetic else []
    )
    if arguments.manifest:
        manifest_path = Path(arguments.manifest).resolve()
        manifest = json.loads(manifest_path.read_text())
        for item in (
            manifest.get("files", [])
            if isinstance(manifest, dict)
            else manifest
        ):
            entry = {"path": item} if isinstance(item, str) else dict(item)
            path = Path(entry["path"])
            if not path.is_absolute():
                path = manifest_path.parent / path
            entry["path"] = str(path.resolve())
            entry.setdefault("name", path.name)
            entries.append(entry)
    for directory in arguments.input_dir:
        for path in sorted(Path(directory).resolve().rglob("*")):
            if path.is_file() and path.suffix.lower() in AUDIO_SUFFIXES:
                entries.append({"name": path.name, "path": str(path)})
    unique = {}
    for entry in entries:
        path = Path(entry["path"]).resolve()
        if not path.is_file():
            raise ValueError(f"input file does not exist: {path}")
        entry["path"] = str(path)
        unique[str(path)] = entry
    return list(unique.values())


def markdown_report(result):
    lines = [
        "<!-- Autonomously generated by an AI agent. -->",
        "",
        "# Paired phase-grid benchmark",
        "",
        (
            "Every row runs in a fresh native test process. Analysis time "
            "excludes decoding and hashing;"
        ),
        (
            "peak RSS is Linux VmHWM since exec through result construction "
            "(before final JSON serialization/I/O), not only algorithm "
            "allocations. Uploaded recordings have"
        ),
        (
            "no annotated ground truth; their pairwise beat agreement is "
            "not an accuracy score."
        ),
        "",
        (
            "| Input | Configuration | Result | BPM | GT beat F1 | GT BPM "
            "error | Analysis ms | Decode ms | Peak RSS MiB |"
        ),
        "| --- | --- | --- | ---: | ---: | ---: | ---: | ---: | ---: |",
    ]

    def number(value, digits=3):
        return (
            f"{value:.{digits}f}" if isinstance(value, (int, float)) else "—"
        )

    for row in result["measurements"]:
        metrics = row.get("truth_metrics", {})
        beats = metrics.get("beats", {})
        name = row["input_name"].replace("|", "\\|")
        lines.append(
            "| "
            + " | ".join(
                (
                    name,
                    row["config"],
                    row.get("status", "error"),
                    number(row.get("bpm")),
                    number(beats.get("f1")),
                    number(metrics.get("absolute_bpm_error")),
                    number(row.get("analysis_ms")),
                    number(row.get("decode_ms")),
                    number(
                        row["peak_rss_bytes"] / 1048576
                        if row.get("peak_rss_bytes")
                        else None
                    ),
                )
            )
            + " |"
        )
    lines += [
        "",
        (
            "JSON contains hashes, all beat times, signed/absolute errors, "
            "per-window tempo and"
        ),
        (
            "coverage, qualified matched-only drift slopes and explicit "
            "tempo-change errors. Match errors"
        ),
        (
            "use chronological one-to-one assignments, not "
            "nearest-neighbor/minimum-error assignments."
        ),
        (
            "Local tempo errors exclude windows crossing explicit "
            "phase/tempo edits. A dash means"
        ),
        (
            "not available or not defined, rather than zero error. "
            "Silence/short/noresult outcomes"
        ),
        (
            "remain separate from execution errors. No timing or "
            "musical-quality threshold is hidden."
        ),
        "",
        f"Runner/PCM verification errors: {len(result['errors'])}.",
        "",
        "<!-- End of autonomously generated AI-agent benchmark report. -->",
        "",
    ]
    return "\n".join(lines)


def run(arguments):
    output = Path(arguments.output_dir).resolve()
    output.mkdir(parents=True, exist_ok=True)
    binary = Path(arguments.test_binary).resolve()
    if not binary.is_file():
        raise ValueError(f"test binary does not exist: {binary}")
    entries = load_inputs(arguments, output)
    if not entries:
        raise ValueError(
            "no inputs: use --synthetic, --input-dir or --manifest"
        )
    configs = []
    for value in arguments.configs:
        backend, mode = value.rsplit(":", 1)
        if mode not in {"auto", "constant", "variable"}:
            raise ValueError(f"invalid configuration: {value}")
        configs.append((value, backend, mode))
    result = {
        "schema_version": 1,
        "method": {
            "fresh_process_per_file_and_config": True,
            "source_and_decoded_pcm_equality_required": True,
            "beat_matching": (
                "chronological one-to-one maximum-cardinality matches"
            ),
            "beat_tolerance_seconds": arguments.tolerance,
            "file_order": "manifest order then sorted directory discovery",
            "config_order": (
                "alternates forward/reverse across files to reduce fixed "
                "cache-order bias"
            ),
            "timing": (
                "native analyzer stage times exclude decoding/hash/export; "
                "subprocess wall includes startup"
            ),
            "memory": (
                "Linux VmHWM since exec through result construction, "
                "excluding final JSON serialization/I/O; includes "
                "Qt/decoder/algorithm; getrusage only diagnostic because "
                "launcher memory may be inherited"
            ),
            "ground_truth": (
                "synthetic only; real recordings have no invented labels"
            ),
        },
        "corpus": entries,
        "measurements": [],
        "pairs": [],
        "errors": [],
    }
    try:
        result["git_head"] = subprocess.check_output(
            [
                "git",
                "-C",
                str(Path(__file__).resolve().parents[1]),
                "rev-parse",
                "HEAD",
            ],
            text=True,
        ).strip()
    except (subprocess.SubprocessError, FileNotFoundError):
        result["git_head"] = None
    repository = Path(__file__).resolve().parents[1]
    sources = [
        repository / "src/analyzer/analyzerbeats.cpp",
        repository / "src/analyzer/plugins/analyzerqueenmarybeats.cpp",
        repository / "src/analyzer/plugins/analyzerphasegrid.cpp",
    ]
    sources.extend(sorted((repository / "lib/phasegrid").glob("*.[ch]*")))
    result["algorithm_source_sha256"] = {
        str(path.relative_to(repository)): sha256(path)
        for path in sources
        if path.is_file()
    }
    for index, entry in enumerate(entries):
        reports = {}
        ordered = configs if index % 2 == 0 else list(reversed(configs))
        for label, backend, mode in ordered:
            key = f"{index:03d}-" + label.replace(":", "_").replace("/", "_")
            destination = output / (key + ".json")
            log_path = output / (key + ".log")
            environment = os.environ.copy()
            environment.update(
                {
                    "MIXXX_PHASEGRID_INPUT": entry["path"],
                    "MIXXX_PHASEGRID_OUTPUT": str(destination),
                    "MIXXX_PHASEGRID_BACKEND": backend,
                    "MIXXX_PHASEGRID_MODE": mode,
                    "QT_QPA_PLATFORM": "offscreen",
                }
            )
            if destination.exists():
                destination.unlink()
            start = time.perf_counter()
            exit_code = None
            problem = None
            with open(log_path, "w") as log:
                try:
                    process = subprocess.run(
                        [
                            str(binary),
                            (
                                "--gtest_filter=PhaseGridFileComparisonTest."
                                "AnalyzeConfiguredFile"
                            ),
                        ],
                        cwd=Path(__file__).resolve().parents[1],
                        env=environment,
                        stdout=log,
                        stderr=subprocess.STDOUT,
                        timeout=arguments.timeout,
                        check=False,
                    )
                    exit_code = process.returncode
                except subprocess.TimeoutExpired:
                    problem = "native benchmark timed out"
            elapsed = (time.perf_counter() - start) * 1000
            if destination.exists():
                report = json.loads(destination.read_text())
            else:
                report = {
                    "status": "error",
                    "error": problem or "native benchmark produced no JSON",
                }
            report.update(
                {
                    "config": label,
                    "input_name": entry["name"],
                    "input_path": entry["path"],
                    "subprocess_exit_code": exit_code,
                    "subprocess_wall_ms": elapsed,
                    "log_path": str(log_path),
                }
            )
            report["truth_metrics"] = truth_metrics(
                entry, report, arguments.tolerance
            )
            if problem or exit_code != 0 or report.get("status") == "error":
                result["errors"].append(
                    {
                        "input": entry["name"],
                        "config": label,
                        "exit_code": exit_code,
                        "error": problem
                        or report.get("error", "nonzero exit"),
                    }
                )
            reports[label] = report
            result["measurements"].append(report)
            print(
                f"{entry['name']} | {label} | {report[(
                    'status'
                )]} | {elapsed:.0f} ms",
                flush=True,
            )
        for (reference, _, _), (candidate, _, _) in itertools.combinations(
            configs, 2
        ):
            try:
                pair = paired_metrics(
                    reports[reference], reports[candidate], arguments.tolerance
                )
                pair["input_name"] = entry["name"]
                pair["ground_truth_available"] = entry.get("truth") is not None
                result["pairs"].append(pair)
            except ValueError as error:
                result["errors"].append(
                    {
                        "input": entry["name"],
                        "reference": reference,
                        "comparison": candidate,
                        "error": str(error),
                    }
                )
        (output / "summary.json").write_text(
            json.dumps(result, indent=2, ensure_ascii=False) + "\n"
        )
        (output / "summary.md").write_text(markdown_report(result))
    return 1 if result["errors"] else 0


class MetricTests(unittest.TestCase):
    def test_exact_beats(self):
        values = [0.5 * i for i in range(20)]
        score = beat_metrics(values, values, 10)
        self.assertEqual(score["f1"], 1)
        self.assertEqual(score["median_absolute_error_ms"], 0)

    def test_duplicate_prediction_cannot_match_twice(self):
        score = beat_metrics([2.0, 3.0], [2.0, 2.01, 3.0], 5)
        self.assertEqual(score["one_to_one_matches"], 2)
        self.assertEqual(score["precision"], 2 / 3)
        self.assertEqual(score["recall"], 1)

    def test_seventy_ms_threshold(self):
        self.assertEqual(beat_metrics([2.0], [2.069], 5)["recall"], 1)
        self.assertEqual(beat_metrics([2.0], [2.071], 5)["recall"], 0)

    def test_signed_error_and_drift(self):
        truth = list(range(2, 30))
        predicted = [t + 0.001 * t for t in truth]
        score = beat_metrics(truth, predicted, 32)
        self.assertAlmostEqual(
            score["drift_slope_ms_per_minute"], 60, places=7
        )
        self.assertGreater(score["median_signed_error_ms"], 0)

    def test_real_recording_has_no_accuracy(self):
        score = truth_metrics(
            {"path": "recording.mp3"}, {"status": "success", "bpm": 120}, 0.07
        )
        self.assertFalse(score["ground_truth_available"])
        self.assertIsNone(score["accuracy"])

    def test_sparse_matching_cannot_claim_absence_of_drift(self):
        truth = list(range(2, 30))
        score = beat_metrics(truth, truth[:5], 32)
        self.assertFalse(score["drift_fit_qualified"])
        self.assertIsNone(score["drift_slope_ms_per_minute"])

    def test_nonfinite_beat_is_not_silently_filtered(self):
        with self.assertRaises(ValueError):
            beat_metrics([float("nan")], [2], 5)

    def test_noresult_remains_distinct(self):
        score = truth_metrics(
            {"truth": {"expected_noresult": True}},
            {"status": "noresult"},
            0.07,
        )
        self.assertIsNone(score["accuracy"])
        self.assertTrue(score["noresult_expected"])

    def test_mismatching_pcm_is_rejected(self):
        with self.assertRaises(ValueError):
            assert_same_pcm({"pcm_sha256": "a"}, {"pcm_sha256": "b"})

    def test_constant_grid_does_not_detect_tempo_change(self):
        truth = {
            "tempo_changes": [
                {"time_seconds": 24, "bpm_before": 120, "bpm_after": 138}
            ]
        }
        report = {
            "local_bpm_windows": [
                {"start_seconds": i, "end_seconds": i + 8, "bpm": 120}
                for i in range(0, 40, 4)
            ]
        }
        self.assertIsNone(
            tempo_change_metrics(truth, report)[0]["estimated_change_seconds"]
        )

    def test_multiple_tempo_changes_use_local_brackets(self):
        truth = {
            "tempo_changes": [
                {"time_seconds": 16, "bpm_before": 120, "bpm_after": 140},
                {"time_seconds": 40, "bpm_before": 140, "bpm_after": 100},
            ]
        }
        windows = []
        for start in range(0, 60, 4):
            center = start + 4
            bpm = 120 if center < 16 else 140 if center < 40 else 100
            windows.append(
                {"start_seconds": start, "end_seconds": start + 8, "bpm": bpm}
            )
        result = tempo_change_metrics(truth, {"local_bpm_windows": windows})
        self.assertTrue(
            all(item["transition_locally_bracketed"] for item in result)
        )
        self.assertEqual(
            [item["estimated_change_seconds"] for item in result], [14, 38]
        )

    def test_phase_edit_does_not_create_local_tempo_truth(self):
        truth = {
            "beat_times_seconds": [
                i * 0.5 + (0.25 if i >= 4 else 0) for i in range(20)
            ],
            "phase_edits": [{"time_seconds": 2}],
            "constant_bpm": 120,
        }
        report = {
            "status": "success",
            "duration_seconds": 10,
            "bpm": 120,
            "beat_times_seconds": truth["beat_times_seconds"],
            "local_bpm_windows": [
                {"start_seconds": 0, "end_seconds": 8, "bpm": 120}
            ],
        }
        score = truth_metrics({"truth": truth}, report, 0.07)
        window = score["local_bpm_windows"][0]
        self.assertIsNone(window["absolute_bpm_error"])
        self.assertEqual(window["excluded_from_tempo_error"], "phase edit")


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--test-binary", default="build/mixxx-test")
    parser.add_argument("--output-dir", default="build/phasegrid-comparison")
    parser.add_argument("--manifest")
    parser.add_argument("--input-dir", action="append", default=[])
    parser.add_argument("--synthetic", action="store_true")
    parser.add_argument("--configs", nargs="+", default=DEFAULT_CONFIGS)
    parser.add_argument("--timeout", type=float, default=300)
    parser.add_argument("--tolerance", type=float, default=0.070)
    parser.add_argument("--self-test", action="store_true")
    arguments = parser.parse_args()
    if arguments.self_test:
        suite = unittest.defaultTestLoader.loadTestsFromTestCase(MetricTests)
        return (
            0
            if unittest.TextTestRunner(verbosity=2).run(suite).wasSuccessful()
            else 1
        )
    if not math.isfinite(arguments.tolerance) or arguments.tolerance <= 0:
        parser.error("tolerance must be finite and positive")
    if not math.isfinite(arguments.timeout) or arguments.timeout <= 0:
        parser.error("timeout must be finite and positive")
    try:
        return run(arguments)
    except (ValueError, OSError, json.JSONDecodeError) as error:
        print(str(error), file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
